<nav class="d-flex flex-wrap align-items-center gap-3 mt-4" aria-label="Halaman ulasan"><?php foreach(array(-1=>'Sebelumnya',1=>'Berikutnya') as $step=>$label):if($report['page']+$step>=1 && $report['page']+$step<=max(1,ceil($report['total']/20))): ?><a class="btn btn-outline-primary" href="<?php echo html_escape(site_url($review_base).'?'.http_build_query($review_query+array('halaman'=>$report['page']+$step))); ?>"><?php echo $label; ?></a><?php endif;endforeach; ?><span>Halaman <?php echo (int)$report['page']; ?> · <?php echo (int)$report['total']; ?> ulasan</span></nav>
